from __future__ import annotations

from dataclasses import dataclass

from foreman.config import FactoryConfig
from foreman.models import Directive, FactoryState, ForemanResult, InterventionType
from foreman.responsibilities import ResponsibilityRegistry, builtin_registry


@dataclass(slots=True)
class FactoryPolicy:
    """Collect responsibility directives and select one under deterministic guardrails."""

    config: FactoryConfig
    responsibilities: ResponsibilityRegistry | None = None
    enforce_iteration_limit: bool = True

    def __post_init__(self) -> None:
        if self.responsibilities is None:
            candidates = builtin_registry(self.config)
            self.responsibilities = candidates.routed(candidates.global_ids())

    def _runtime_directive(
        self,
        state: FactoryState,
        action: InterventionType,
        reason: str,
        *,
        priority: int,
    ) -> Directive:
        return Directive(
            action=action,
            reason=reason,
            assessment_iteration=max(1, state.iteration),
            responsibility_id="foreman.runtime",
            priority=priority,
        )

    def configuration_error(self, state: FactoryState) -> Directive | None:
        for worker in state.workers:
            if worker.configuration_error:
                return self._runtime_directive(
                    state, InterventionType.ESCALATE, worker.configuration_error, priority=1000,
                )
        return None

    def evaluate(self, state: FactoryState, result: ForemanResult) -> ForemanResult:
        assert self.responsibilities is not None
        proposed = self.responsibilities.directives(state, result)

        configuration_error = self.configuration_error(state)
        if configuration_error is not None:
            proposed.append(configuration_error)

        # Hard iteration limits remain a runtime invariant, not responsibility semantics.
        if self.enforce_iteration_limit and state.iteration >= state.max_iterations:
            proposed.append(
                self._runtime_directive(
                    state,
                    InterventionType.ESCALATE,
                    "maximum Foreman iterations reached",
                    priority=950,
                )
            )

        if not proposed:
            selected = self._runtime_directive(
                state,
                InterventionType.CONTINUE,
                "active worker may continue",
                priority=0,
            )
        else:
            # `max` is stable, so responsibility order supplies deterministic tie-breaking.
            selected = max(
                proposed,
                key=lambda directive: (
                    directive.priority,
                    directive.confidence if directive.confidence is not None else -1.0,
                ),
            )

        if selected.action is InterventionType.RETRY_WORKER:
            retry_allowed = state.retry_count < self.config.max_retries
            worker_allowed = len(state.workers) < self.config.max_workers
            if not retry_allowed or not worker_allowed:
                selected = self._runtime_directive(
                    state,
                    InterventionType.ESCALATE,
                    "worker retry limit reached",
                    priority=selected.priority,
                )
                proposed.append(selected)
        elif selected.action is InterventionType.START_VERIFIER:
            if len(state.workers) >= self.config.max_workers:
                selected = self._runtime_directive(
                    state,
                    InterventionType.ESCALATE,
                    "verification needed but worker limit reached",
                    priority=selected.priority,
                )
                proposed.append(selected)
        elif selected.action is InterventionType.START_WORKER:
            if len(state.workers) >= self.config.max_workers:
                selected = self._runtime_directive(
                    state,
                    InterventionType.ESCALATE,
                    "worker limit reached before completion",
                    priority=selected.priority,
                )
                proposed.append(selected)

        return result.with_directives(proposed, selected)

    def decide(self, state: FactoryState, result: ForemanResult) -> Directive:
        evaluated = self.evaluate(state, result)
        assert evaluated.selected_directive is not None
        return evaluated.selected_directive

    self.usage_recorder = usage_recorder or DecisionUsageRecorder()

@property
def model(self) -> str:
    return self.adapter.model

@model.setter
def model(self, value: str) -> None:
    self.adapter.model = value

async def assess(
    self,
    observation: FactoryObservation,
    checks: Sequence[Check],
) -> ForemanResult:
    groups: dict[tuple[str, ...], list[Check]] = {}
    for check in checks:
        groups.setdefault(evidence_for(check), []).append(check)

    plans = []
    try:
        for providers, group in groups.items():
            fitted = self.budget.fit(
                observation.state_for(providers),
                {check.key: check.instructions for check in group},
            )
            if "evidence_budget" in fitted.state:
                logger.info(
                    "Compacted decision model evidence: %s", fitted.measurements,
                )
            plans.append((fitted, group))
    except RequestBudgetError as error:
        raise ForemanModelError(str(error)) from error

    async def assess_group(request: BudgetedRequest, group: Sequence[Check]) -> ForemanResult:
        result = await asyncio.wait_for(
            self.adapter.evaluate(
                request.state, {check.key: check.instructions for check in group},
            ),
            timeout=self.timeout_seconds + 0.5,
        )
        self.usage_recorder.record(
            result.response, request, purpose="assessment", model=self.adapter.model,
            provider=self.adapter.provider,
        )
        return normalize_check_results(result.values, group)

    try:
        tasks = [asyncio.create_task(assess_group(request, group)) for request, group in plans]
        try:
            results = await asyncio.gather(*tasks)
        except BaseException:
            # Settle sibling requests before a runtime can close the owned client.
            for task in tasks:
                task.cancel()
            await asyncio.gather(*tasks, return_exceptions=True)
            raise
        merged: dict[str, dict[str, float]] = {}
        for result in results:
            for responsibility_id, values in result.checks.items():
                merged.setdefault(responsibility_id, {}).update(values)
        return ForemanResult(checks=merged)
    except TimeoutError as error:
        raise ForemanModelError(f"{self.adapter.provider} assessment timed out") from error
    except ForemanModelError:
        raise
    except Exception as error:
        message = f"{self.adapter.provider} assessment failed: {type(error).__name__}: {error}"
        raise ForemanModelError(message) from error

async def close(self) -> None:
    await self.adapter.close()

    if worker.last_steered_at is not None:
        since_steer = (datetime.now(UTC) - worker.last_steered_at).total_seconds()
        if since_steer < config.steering_grace_seconds:
            return _directive(
                state,
                responsibility_id=responsibility_id,
                action=InterventionType.CONTINUE,
                reason="active worker is within the post-steering grace period",
                priority=900,
                worker_id=active_id,
                confidence=confidence,
            )
    if (
        config.steering_enabled
        and worker.supports_steering
        and worker.steer_count < config.max_steers_per_worker
    ):
        action = InterventionType.STEER_WORKER
    else:
        action = InterventionType.STOP_WORKER
    return _directive(
        state,
        responsibility_id=responsibility_id,
        action=action,
        reason=reason,
        priority=900,
        worker_id=active_id,
        confidence=confidence,
    )


@dataclass(slots=True)
class HumanEscalationResponsibility(_CheckConfiguredResponsibility):
    config: FactoryConfig
    id: str = HUMAN_ESCALATION
    required_check_ids: ClassVar[frozenset[str]] = frozenset({"needs_human"})
    required_minimum_keys: ClassVar[frozenset[str]] = frozenset(
        {f"{HUMAN_ESCALATION}__needs_human"}
    )

    def directives(self, state: FactoryState, result: ForemanResult) -> list[Directive]:
        score = result.probability(self.id, "needs_human")
        if score < self.minimum(self.id, "needs_human"):
            return []
        return [
            _directive(
                state,
                responsibility_id=self.id,
                action=InterventionType.ESCALATE,
                reason="semantic assessment requires human input",
                priority=1_000,
                confidence=score,
            )
        ]


@dataclass(slots=True)
class RepositoryInstructionsResponsibility(_CheckConfiguredResponsibility):
    config: FactoryConfig
    id: str = REPOSITORY_INSTRUCTIONS

    files: list[str] = []
    for responsibility in self._responsibilities:
        configured = getattr(responsibility, "instruction_files", ())
        for filename in configured:
            if filename not in files:
                files.append(filename)
    return tuple(files)

def directives(self, state: FactoryState, result: ForemanResult) -> list[Directive]:
    proposals: list[Directive] = []
    for responsibility in self._responsibilities:
        for directive in responsibility.directives(state, result):
            if directive.responsibility_id != responsibility.id:
                raise ValueError(
                    f"directive belongs to {directive.responsibility_id!r}, "
                    f"not {responsibility.id!r}"
                )
            proposals.append(directive)
    return proposals
